import type { Response } from 'express';

/** Sends generated bytes (PDF, certificate) with a fixed type, no sniffing and no caching by default. */
export function binary(res: Response, type: string, body: Buffer, cache = 'no-store') {
  res.setHeader('Content-Type', type);
  res.setHeader('Cache-Control', cache);
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.end(body);
}
